import { initializeApp } from "firebase/app";
import {
  getAuth,
  signInWithRedirect,
  signInWithPopup,
  GoogleAuthProvider,
} from "firebase/auth";

const firebaseConfig = {
  apiKey: "AIzaSyBOF0naiTvwXw0fcctBhoQGqS5FehkYwtM",
  authDomain: "capstone-project-shop-db.firebaseapp.com",
  projectId: "capstone-project-shop-db",
  storageBucket: "capstone-project-shop-db.firebasestorage.app",
  messagingSenderId: "651883695815",
  appId: "1:651883695815:web:ec701bbd14aa262009f8e2",
};

const firebaseApp = initializeApp(firebaseConfig);

const provider = new GoogleAuthProvider();

provider.setCustomParameters({
  prompt: "select_account",
});

export const auth = getAuth();
export const signInWithGooglePopup = () => signInWithPopup(auth, provider);
